def labels_of(n):
    t = open(os.path.join(A, 'issues', 'open', f'{n}.md'), encoding='utf-8', errors='replace').read()
    head = t.split('\n## BODY', 1)[0]
    author = re.search(r'author: (\S+)', head).group(1)
    labs = [x.strip() for x in re.search(r'^labels: (.*)$', head, re.M).group(1).split(',')]
    return author, labs

def derive(n):
    author, labs = labels_of(n)
    ac = 'owner' if author == 'Ensrick' else ('rain' if author == 'RainReligion' else 'external')
    if 'crash' in labs: ty = 'crash'
    elif 'tooling' in labs: ty = 'tooling'
    elif 'bug' in labs: ty = 'bug'
    elif 'feature' in labs: ty = 'feature'
    elif 'enhancement' in labs: ty = 'enhancement'
    else: ty = 'question'
    life = [l for l in ('verify-fix', 'diagnostics-armed', 'not-started') if l in labs]
    life = life[0] if life else 'none'
    if 'blocked' in labs: life += '+blocked'
    if 'coop-required' in labs: life += '+coop-required'
    pr = [l for l in labs if re.match(r'^[0-3]-', l)]
    return ac, ty, life, (pr[0] if pr else 'none')

HEADER = ['number', 'mod', 'author_class', 'type', 'lifecycle', 'priority', 'summary', 'cluster', 'fix_state',
          'verification_class', 'auto_check', 'disposition', 'related', 'confidence', 'note']
out, warn = [], []
for line in ROWS.strip().split('\n'):
    p = line.split('|')
    if len(p) != 11:
        sys.exit(f'bad field count {len(p)}: {line[:60]}')
    n, mod, summary, cluster, fix, cls, auto, disp, rel, conf, note = [x.strip() for x in p]
    n = int(n)
    ac, ty, life, pr = derive(n)
    if n in (660,): ty = 'bug'      # umbrella carries a crash label without a crash
    if n in (476,): ty = 'bug'      # crash label has no crash evidence in the thread
    if len(summary.split()) > 20: warn.append(f'#{n} summary {len(summary.split())} words')
    if len(auto.split()) > 30: warn.append(f'#{n} auto_check {len(auto.split())} words')
    for f in (summary, auto, note, rel):
        if '\t' in f: sys.exit('tab in field')
    out.append([str(n), mod, ac, ty, life, pr, summary, cluster, fix, cls, auto, disp, rel, conf, note])
nums = [int(r[0]) for r in out]
dig = [int(m) for m in re.findall(r'^=== #(\d+) \[open\]', open(os.path.join(A, 'issues', 'digest', 'D1_cwv_woc_open_digest.md'), encoding='utf-8').read(), re.M)]
assert len(nums) == len(set(nums)), 'duplicate rows'
missing = sorted(set(dig) - set(nums)); extra = sorted(set(nums) - set(dig))
print('rows', len(out), 'bucket', len(dig), 'missing', missing, 'extra', extra)
with open(os.path.join(A, 'findings', 'D1_ledger.tsv'), 'w', encoding='utf-8', newline='\n') as f:
    f.write('\t'.join(HEADER) + '\n')
    for r in sorted(out, key=lambda r: int(r[0])):
        f.write('\t'.join(r) + '\n')
for w in warn: print('WARN', w)
def tab(i, title):
    c = collections.Counter(r[i] for r in out)
    print(title + ': ' + ', '.join(f'{k}={v}' for k, v in c.most_common()))
tab(2, 'author'); tab(3, 'type'); tab(9, 'class'); tab(7, 'cluster'); tab(8, 'fix_state'); tab(13, 'confidence')
